def cargar_lista_productos():
    """
    Lee productos.txt, un producto por línea.

    Las líneas vacías y las que empiezan con # se ignoran.
    Si el archivo falta o está vacío, conserva la lista integrada.
    """
    ruta = Path(__file__).resolve().with_name("productos.txt")
    if not ruta.is_file():
        return list(CATEGORIAS_PRODUCTO)

    productos = []
    vistos = set()

    try:
        lineas = ruta.read_text(encoding="utf-8-sig").splitlines()
    except (OSError, UnicodeError):
        return list(CATEGORIAS_PRODUCTO)

    for linea in lineas:
        producto = linea.strip()
        if not producto or producto.startswith("#"):
            continue

        clave = producto.casefold()
        if clave in vistos:
            continue

        vistos.add(clave)
        productos.append(producto)

    return productos or list(CATEGORIAS_PRODUCTO)


CATEGORIAS_PRODUCTO = cargar_lista_productos()

