def entero_seguro(valor, predeterminado=0):
    try:
        if pd.isna(valor):
            return predeterminado
        return int(valor)
    except (TypeError, ValueError, OverflowError):
        return predeterminado


def decimal_seguro(valor, predeterminado=0.0):
    try:
        if pd.isna(valor):
            return predeterminado
        return float(valor)
    except (TypeError, ValueError, OverflowError):
        return predeterminado


def fecha_iso_segura(valor):
    """Convierte fechas de Streamlit/Pandas a YYYY-MM-DD."""
    try:
        if pd.isna(valor):
            return datetime.today().date().isoformat()
    except (TypeError, ValueError):
        pass

    if hasattr(valor, "date") and not isinstance(valor, str):
        try:
            valor = valor.date()
        except (TypeError, ValueError):
            pass

    if hasattr(valor, "isoformat"):
        try:
            return valor.isoformat()
        except (TypeError, ValueError):
            pass

    fecha = pd.to_datetime(valor, errors="coerce")
    if pd.isna(fecha):
        return datetime.today().date().isoformat()
    return fecha.date().isoformat()


def ahora_utc():
    return datetime.now(timezone.utc).isoformat()


def leer_configuracion():
    """Lee las mismas credenciales usadas por la app Supabase existente."""
    try:
        url = str(st.secrets["supabase"]["url"]).strip()
        secret_key = str(st.secrets["supabase"]["secret_key"]).strip()
        usuarios = {
            str(nombre).strip().lower(): str(clave)
            for nombre, clave in st.secrets["usuarios"].items()
        }
    except (KeyError, FileNotFoundError, AttributeError) as exc:
        st.error(
            "Falta la configuración de Supabase o de usuarios. "
            "Conserva en Streamlit Secrets las mismas claves que ya usa "
            "deposito_supabase.py."
        )
        st.stop()
        raise RuntimeError("Configuración de Supabase incompleta") from exc

    if not url.startswith("https://") or not secret_key or not usuarios:
        st.error("La URL, la clave secreta o la lista de usuarios no son válidas.")
        st.stop()

    return url, secret_key, usuarios


@st.cache_resource
def obtener_supabase() -> Client:
    """Crea una conexión reutilizable al proyecto Supabase existente."""
    url, secret_key, _ = leer_configuracion()
    return create_client(url, secret_key)


def usuario_actual():
    return str(st.session_state.get("usuario", "desconocido"))


def nombre_usuario_normalizado():
    """Normaliza el usuario guardado en la sesión."""
    valor = str(usuario_actual() or "").strip().lower()
    valor = "".join(
        caracter
        for caracter in unicodedata.normalize("NFKD", valor)
        if not unicodedata.combining(caracter)
    )
    return re.sub(r"[^a-z0-9]+", "", valor)


def usuario_es_toni():
    nombre = nombre_usuario_normalizado()
    return nombre in {"toni", "tony"} or nombre.startswith("toni")


def sede_del_usuario():
    """Relaciona el usuario autenticado con su tabla de notas."""
    nombre = nombre_usuario_normalizado()
    if "santacruz" in nombre or nombre == "santacruiz":
        return "SANTACRUZ"
    if "tarija" in nombre:
        return "TARIJA"
    if "camioncito" in nombre:
        return "CAMIONCITO"
    return None


def puede_editar_sede(sede):
    """Toni edita todas las notas; cada sede edita únicamente la suya."""
    sede = str(sede or "").strip().upper()
    return usuario_es_toni() or sede_del_usuario() == sede


def categorias_disponibles(dataframe=None):
    """
    Conserva las categorías del depósito y añade los productos libres
    escritos en las notas, sin obligarlos a existir en inventario.
    """
    opciones = list(CATEGORIAS_PRODUCTO)
    if dataframe is not None and "Categoría" in dataframe.columns:
        for valor in dataframe["Categoría"].fillna("").astype(str):
            categoria = valor.strip()
            if categoria and categoria not in opciones:
                opciones.append(categoria)
    return opciones or [""]


