def exigir_columna_descripcion():
    """
    Comprueba que Supabase tenga la columna public.ventas.descripcion.
    Evita mostrar un guardado falso cuando la base no admite la descripción.
    """
    if st.session_state.get("_columna_descripcion_ok"):
        return

    try:
        (
            obtener_supabase()
            .table("ventas")
            .select("descripcion")
            .limit(1)
            .execute()
        )
        st.session_state["_columna_descripcion_ok"] = True
    except Exception:
        st.error(
            "Falta la columna descripcion en Supabase. Ejecuta primero el "
            "archivo agregar_descripcion_supabase.sql en el SQL Editor."
        )
        st.stop()


def exigir_login():
    """Mantiene el acceso protegido de la versión Supabase original."""
    if st.session_state.get("autorizado"):
        return

    _, _, usuarios = leer_configuracion()
    st.markdown("## 🔐 Acceso a Notas de Venta")
    nombre = st.text_input("Usuario").strip().lower()
    clave = st.text_input("Contraseña", type="password")

    if st.button("Entrar", use_container_width=True):
        clave_guardada = usuarios.get(nombre)
        if clave_guardada and hmac.compare_digest(clave, clave_guardada):
            st.session_state.autorizado = True
            st.session_state.usuario = nombre
            st.rerun()
        else:
            st.error("Usuario o contraseña incorrectos.")

    st.stop()


def payload_nota(sede, fila, incluir_auditoria=False):
    """Crea una actualización parcial sin tocar columnas de costos ajenas."""
    categoria = str(fila.get("Categoría", "") or "").strip()
    descripcion = str(fila.get("Descripción", "") or "").strip()

    payload = {
        "sede": sede,
        "nro_nota": max(0, entero_seguro(fila.get("Nro Nota", 0))),
        "fecha": fecha_iso_segura(fila.get("Fecha")),
        "cliente": str(fila.get("Cliente", "") or ""),
        "categoria": categoria,
        "descripcion": descripcion,
        "cantidad": max(0, entero_seguro(fila.get("Cantidad", 0))),
        "precio_unitario": round(
            max(0.0, decimal_seguro(fila.get("Precio Unitario (Bs.)", 0.0))),
            2,
        ),
        "precio_dolar": round(
            max(0.0, decimal_seguro(fila.get("Precio en Dólar", 0.0))),
            2,
        ),
    }

    if incluir_auditoria:
        payload["actualizado_por"] = usuario_actual()
        payload["updated_at"] = ahora_utc()

    return payload


def nombre_sede_legible(sede):
    """Devuelve el nombre de la sede listo para mostrar en documentos."""
    nombres = {
        "SANTACRUZ": "Santa Cruz",
        "TARIJA": "Tarija",
        "CAMIONCITO": "Camioncito",
    }
    return nombres.get(str(sede).upper(), str(sede).title())


def generar_pdf_nota(dataframe_nota, sede, numero_nota):
    """Genera una nota de pedido clásica en PDF sin dependencias externas."""
    df_nota = dataframe_nota.copy()
    if df_nota.empty:
        raise ValueError("La nota seleccionada no contiene datos.")

    df_nota["Fecha"] = pd.to_datetime(df_nota["Fecha"], errors="coerce")
    df_nota["Cantidad"] = pd.to_numeric(
        df_nota["Cantidad"], errors="coerce"
    ).fillna(0)
    df_nota["Precio Unitario (Bs.)"] = pd.to_numeric(
        df_nota["Precio Unitario (Bs.)"], errors="coerce"
    ).fillna(0.0)
    df_nota["Precio Total (Bs.)"] = pd.to_numeric(
        df_nota["Precio Total (Bs.)"], errors="coerce"
    ).fillna(0.0)
    df_nota["Precio en Dólar"] = pd.to_numeric(
        df_nota["Precio en Dólar"], errors="coerce"
    ).fillna(0.0)

    primera_fila = df_nota.iloc[0]
    fecha = primera_fila.get("Fecha")
    fecha_texto = fecha.strftime("%d/%m/%Y") if pd.notna(fecha) else "-"
    cliente = str(primera_fila.get("Cliente", "") or "Sin especificar")
    sede_texto = nombre_sede_legible(sede)

    total_bs = float(df_nota["Precio Total (Bs.)"].sum())
    total_dolar = float(df_nota["Precio en Dólar"].sum())
    total_cantidad = int(df_nota["Cantidad"].sum())

    ancho_pagina = 595.28
    alto_pagina = 841.89
    margen_x = 42.0
    ancho_tabla = 510.0
    columnas = [220.0, 45.0, 90.0, 85.0, 70.0]
    encabezados = ["Producto / descripción", "Cant.", "P. unitario Bs.", "Total Bs.", "Total $"]
    rosa = (0.843, 0.098, 0.478)
    rosa_claro = (1.0, 0.941, 0.973)
    rosa_total = (1.0, 0.878, 0.933)
    gris = (0.72, 0.72, 0.72)

    def limpiar_texto(valor):
        texto = str(valor if valor is not None else "")
        texto = texto.replace("\r", " ").replace("\n", " ")
        return " ".join(texto.split())

    def cortar(texto, maximo):
        texto = limpiar_texto(texto)
        if len(texto) <= maximo:
            return texto
        return texto[: maximo - 3].rstrip() + "..."

    def escapar_pdf(texto):
        return (
            limpiar_texto(texto)
            .replace("\\", "\\\\")
            .replace("(", "\\(")
            .replace(")", "\\)")
        )

    def ancho_estimado(texto, tamano):
        return len(limpiar_texto(texto)) * tamano * 0.51

    def texto_pdf(
        comandos,
        texto,
        x,
        y,
        tamano=10,
        negrita=False,
        color=(0, 0, 0),
        alineacion="izquierda",
    ):
        texto = limpiar_texto(texto)
        if alineacion == "centro":
            x -= ancho_estimado(texto, tamano) / 2
        elif alineacion == "derecha":
            x -= ancho_estimado(texto, tamano)
        fuente = "F2" if negrita else "F1"
        comandos.extend(
            [
                f"{color[0]:.3f} {color[1]:.3f} {color[2]:.3f} rg",
                "BT",
                f"/{fuente} {tamano:.2f} Tf",
                f"1 0 0 1 {x:.2f} {y:.2f} Tm",
                f"({escapar_pdf(texto)}) Tj",
                "ET",
            ]
        )

    def rectangulo(comandos, x, y, ancho, alto, relleno=None, borde=None, grosor=0.5):
        if relleno is not None:
            comandos.append(
                f"{relleno[0]:.3f} {relleno[1]:.3f} {relleno[2]:.3f} rg"
            )
        if borde is not None:
            comandos.append(
                f"{borde[0]:.3f} {borde[1]:.3f} {borde[2]:.3f} RG"
            )
            comandos.append(f"{grosor:.2f} w")
        comandos.append(f"{x:.2f} {y:.2f} {ancho:.2f} {alto:.2f} re")
        if relleno is not None and borde is not None:
            comandos.append("B")
        elif relleno is not None:
            comandos.append("f")
        else:
            comandos.append("S")

    def linea(comandos, x1, y1, x2, y2, color=(0, 0, 0), grosor=0.5):
        comandos.extend(
            [
                f"{color[0]:.3f} {color[1]:.3f} {color[2]:.3f} RG",
                f"{grosor:.2f} w",
                f"{x1:.2f} {y1:.2f} m {x2:.2f} {y2:.2f} l S",
            ]
        )

    def dibujar_encabezado_pagina(comandos, numero_pagina):
        texto_pdf(
            comandos,
            "NUEVO RUMBOS",
            ancho_pagina / 2,
            746.31,
            tamano=22,
            negrita=True,
            color=rosa,
            alineacion="centro",
        )
        subtitulo = "NOTA DE PEDIDO"
        if numero_pagina > 1:
            subtitulo += f" - PÁGINA {numero_pagina}"
        texto_pdf(
            comandos,
            subtitulo,
            ancho_pagina / 2,
            722.31,
            tamano=12,
            negrita=True,
            color=(0.18, 0.18, 0.18),
            alineacion="centro",
        )
        linea(comandos, margen_x, 709.31, ancho_pagina - margen_x, 709.31, rosa, 1.4)

    def dibujar_cabecera_datos(comandos):
        texto_pdf(
            comandos,
            f"Nro. de nota: {entero_seguro(numero_nota)}",
            margen_x,
            685.31,
            tamano=10,
            negrita=True,
        )
        texto_pdf(
            comandos,
            f"Fecha: {fecha_texto}",
            ancho_pagina - margen_x,
            685.31,
            tamano=10,
            negrita=True,
            alineacion="derecha",
        )
        texto_pdf(
            comandos,
            f"Cliente: {cortar(cliente, 55)}",
            margen_x,
            667.31,
            tamano=10,
        )
        texto_pdf(
            comandos,
            f"Sede: {sede_texto}",
            ancho_pagina - margen_x,
            667.31,
            tamano=10,
            alineacion="derecha",
        )
        texto_pdf(
            comandos,
            "NIT 323894023",
            ancho_pagina - margen_x,
            649.31,
            tamano=10,
            negrita=True,
            alineacion="derecha",
        )

    def dibujar_fila(comandos, y_superior, valores, relleno=None, negrita=False):
        alto_fila = 23.0
        x = margen_x
        rectangulo(
            comandos,
            margen_x,
            y_superior - alto_fila,
            ancho_tabla,
            alto_fila,
            relleno=relleno,
            borde=gris,
            grosor=0.45,
        )
        for ancho_columna in columnas[:-1]:
            x += ancho_columna
            linea(
                comandos,
                x,
                y_superior - alto_fila,
                x,
                y_superior,
                gris,
                0.45,
            )

        x = margen_x
        for indice, (valor, ancho_columna) in enumerate(zip(valores, columnas)):
            if indice == 0:
                texto_pdf(
                    comandos,
                    cortar(valor, 38),
                    x + 5,
                    y_superior - 15.5,
                    tamano=8.6,
                    negrita=negrita,
                )
            elif indice == 1:
                texto_pdf(
                    comandos,
                    valor,
                    x + ancho_columna / 2,
                    y_superior - 15.5,
                    tamano=8.4,
                    negrita=negrita,
                    alineacion="centro",
                )
            else:
                texto_pdf(
                    comandos,
                    valor,
                    x + ancho_columna - 5,
                    y_superior - 15.5,
                    tamano=8.4,
                    negrita=negrita,
                    alineacion="derecha",
                )
            x += ancho_columna
        return y_superior - alto_fila

    def dibujar_encabezado_tabla(comandos, y_superior):
        alto = 25.0
        rectangulo(
            comandos,
            margen_x,
            y_superior - alto,
            ancho_tabla,
            alto,
            relleno=rosa,
            borde=rosa,
            grosor=0.5,
        )
        x = margen_x
        for ancho_columna in columnas[:-1]:
            x += ancho_columna
            linea(comandos, x, y_superior - alto, x, y_superior, (1, 1, 1), 0.5)
        x = margen_x
        for titulo, ancho_columna in zip(encabezados, columnas):
            texto_pdf(
                comandos,
                titulo,
                x + ancho_columna / 2,
                y_superior - 16.5,
                tamano=8.2,
                negrita=True,
                color=(1, 1, 1),
                alineacion="centro",
            )
            x += ancho_columna
        return y_superior - alto

    paginas = []
    comandos = []
    numero_pagina = 1
    dibujar_encabezado_pagina(comandos, numero_pagina)
    dibujar_cabecera_datos(comandos)
    y = dibujar_encabezado_tabla(comandos, 627.31)

    alternar = False
    for _, fila in df_nota.iterrows():
        if y - 23 < 190:
            paginas.append("\n".join(comandos))
            numero_pagina += 1
            comandos = []
            dibujar_encabezado_pagina(comandos, numero_pagina)
            y = dibujar_encabezado_tabla(comandos, 691.31)
            alternar = False

        producto = str(fila.get("Categoría", "") or "").strip()
        descripcion = str(fila.get("Descripción", "") or "").strip()
        producto_descripcion = (
            f"{producto} - {descripcion}"
            if producto and descripcion
            else producto or descripcion
        )
        valores = [
            producto_descripcion,
            str(entero_seguro(fila.get("Cantidad", 0))),
            f"{decimal_seguro(fila.get('Precio Unitario (Bs.)', 0.0)):,.2f}",
            f"{decimal_seguro(fila.get('Precio Total (Bs.)', 0.0)):,.2f}",
            f"{decimal_seguro(fila.get('Precio en Dólar', 0.0)):,.2f}",
        ]
        y = dibujar_fila(
            comandos,
            y,
            valores,
            relleno=rosa_claro if alternar else (1, 1, 1),
        )
        alternar = not alternar

    if y - 23 < 190:
        paginas.append("\n".join(comandos))
        numero_pagina += 1
        comandos = []
        dibujar_encabezado_pagina(comandos, numero_pagina)
        y = dibujar_encabezado_tabla(comandos, 691.31)

    y = dibujar_fila(
        comandos,
        y,
        [
            "TOTALES",
            str(total_cantidad),
            "",
            f"{total_bs:,.2f}",
            f"{total_dolar:,.2f}",
        ],
        relleno=rosa_total,
        negrita=True,
    )
    # Firma y NIT centrados, elevados 3 cm respecto a la posición anterior.
    texto_pdf(
        comandos,
        "FIRMA Y NIT",
        ancho_pagina / 2,
        157.04,
        tamano=10,
        negrita=True,
        color=(0.12, 0.12, 0.12),
        alineacion="centro",
    )
    linea(
        comandos,
        ancho_pagina / 2 - 105,
        143.04,
        ancho_pagina / 2 + 105,
        143.04,
        color=(0.12, 0.12, 0.12),
        grosor=0.9,
    )
    texto_pdf(
        comandos,
        "Documento generado desde el sistema de notas de venta.",
        ancho_pagina / 2,
        28,
        tamano=8,
        color=(0.45, 0.45, 0.45),
        alineacion="centro",
    )
    paginas.append("\n".join(comandos))

    objetos = {
        1: b"<< /Type /Catalog /Pages 2 0 R >>",
        3: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica /Encoding /WinAnsiEncoding >>",
        4: b"<< /Type /Font /Subtype /Type1 /BaseFont /Helvetica-Bold /Encoding /WinAnsiEncoding >>",
    }
    referencias_paginas = []
    for indice, contenido in enumerate(paginas):
        id_pagina = 5 + indice * 2
        id_contenido = id_pagina + 1
        referencias_paginas.append(f"{id_pagina} 0 R")
        contenido_bytes = contenido.encode("cp1252", errors="replace")
        objetos[id_contenido] = (
            f"<< /Length {len(contenido_bytes)} >>\nstream\n".encode("ascii")
            + contenido_bytes
            + b"\nendstream"
        )
        objetos[id_pagina] = (
            f"<< /Type /Page /Parent 2 0 R "
            f"/MediaBox [0 0 {ancho_pagina:.2f} {alto_pagina:.2f}] "
            f"/Resources << /Font << /F1 3 0 R /F2 4 0 R >> >> "
            f"/Contents {id_contenido} 0 R >>"
        ).encode("ascii")

    objetos[2] = (
        f"<< /Type /Pages /Count {len(referencias_paginas)} "
        f"/Kids [{' '.join(referencias_paginas)}] >>"
    ).encode("ascii")

    max_id = max(objetos)
    pdf = bytearray(b"%PDF-1.4\n%\xe2\xe3\xcf\xd3\n")
    offsets = [0] * (max_id + 1)
    for object_id in range(1, max_id + 1):
        offsets[object_id] = len(pdf)
        pdf.extend(f"{object_id} 0 obj\n".encode("ascii"))
        pdf.extend(objetos[object_id])
        pdf.extend(b"\nendobj\n")

    inicio_xref = len(pdf)
    pdf.extend(f"xref\n0 {max_id + 1}\n".encode("ascii"))
    pdf.extend(b"0000000000 65535 f \n")
    for object_id in range(1, max_id + 1):
        pdf.extend(f"{offsets[object_id]:010d} 00000 n \n".encode("ascii"))
    pdf.extend(
        (
            f"trailer\n<< /Size {max_id + 1} /Root 1 0 R >>\n"
            f"startxref\n{inicio_xref}\n%%EOF"
        ).encode("ascii")
    )
    return bytes(pdf)

def generar_excel_rango(dataframe_rango, sede, fecha_inicio, fecha_fin):
    """Genera un Excel profesional con todas las columnas del rango."""
    df_excel = dataframe_rango.copy()
    if "Eliminar" in df_excel.columns:
        df_excel = df_excel.drop(columns=["Eliminar"])

    columnas = [
        "Nro Nota",
        "Fecha",
        "Cliente",
        "Categoría",
        "Descripción",
        "Cantidad",
        "Precio Unitario (Bs.)",
        "Precio Total (Bs.)",
        "Precio en Dólar",
    ]
    df_excel = df_excel.reindex(columns=columnas)
    df_excel.insert(0, "Sede", nombre_sede_legible(sede))
    df_excel["Fecha"] = pd.to_datetime(df_excel["Fecha"], errors="coerce")

    salida = BytesIO()
    with pd.ExcelWriter(
        salida,
        engine="xlsxwriter",
        datetime_format="dd/mm/yyyy",
        date_format="dd/mm/yyyy",
    ) as escritor:
        nombre_hoja = f"Notas {nombre_sede_legible(sede)}"[:31]
        df_excel.to_excel(
            escritor,
            sheet_name=nombre_hoja,
            startrow=4,
            header=False,
            index=False,
        )

        libro = escritor.book
        hoja = escritor.sheets[nombre_hoja]

        formato_titulo = libro.add_format(
            {
                "bold": True,
                "font_size": 18,
                "font_color": "#FFFFFF",
                "bg_color": "#D7197A",
                "align": "center",
                "valign": "vcenter",
            }
        )
        formato_rango = libro.add_format(
            {
                "bold": True,
                "font_color": "#333333",
                "bg_color": "#FFE0EE",
                "align": "center",
                "valign": "vcenter",
            }
        )
        formato_fecha = libro.add_format({"num_format": "dd/mm/yyyy"})
        formato_numero = libro.add_format({"num_format": "#,##0"})
        formato_bs = libro.add_format({"num_format": '#,##0.00 "Bs."'})
        formato_usd = libro.add_format({"num_format": '$ #,##0.00'})

        ultima_columna = len(df_excel.columns) - 1
        hoja.merge_range(
            0,
            0,
            0,
            ultima_columna,
            f"NUEVO RUMBOS - NOTAS {nombre_sede_legible(sede).upper()}",
            formato_titulo,
        )
        hoja.merge_range(
            1,
            0,
            1,
            ultima_columna,
            (
                "Rango de fechas: "
                f"{fecha_inicio.strftime('%d/%m/%Y')} - "
                f"{fecha_fin.strftime('%d/%m/%Y')}"
            ),
            formato_rango,
        )
        hoja.set_row(0, 28)
        hoja.set_row(1, 22)

        fila_encabezado = 3
        fila_final = fila_encabezado + len(df_excel)
        hoja.add_table(
            fila_encabezado,
            0,
            fila_final,
            ultima_columna,
            {
                "name": f"TablaNotas{str(sede).title().replace('_', '')}",
                "style": "Table Style Medium 4",
                "columns": [
                    {"header": columna}
                    for columna in df_excel.columns
                ],
            },
        )

        anchos = {
            "Sede": 15,
            "Nro Nota": 11,
            "Fecha": 13,
            "Cliente": 28,
            "Categoría": 26,
            "Descripción": 38,
            "Cantidad": 11,
            "Precio Unitario (Bs.)": 21,
            "Precio Total (Bs.)": 19,
            "Precio en Dólar": 18,
        }
        for indice, columna in enumerate(df_excel.columns):
            formato = None
            if columna == "Fecha":
                formato = formato_fecha
            elif columna == "Cantidad" or columna == "Nro Nota":
                formato = formato_numero
            elif columna in {"Precio Unitario (Bs.)", "Precio Total (Bs.)"}:
                formato = formato_bs
            elif columna == "Precio en Dólar":
                formato = formato_usd
            hoja.set_column(
                indice,
                indice,
                anchos.get(columna, 15),
                formato,
            )

        hoja.freeze_panes(4, 0)
        hoja.set_landscape()
        hoja.fit_to_pages(1, 0)
        hoja.set_margins(left=0.25, right=0.25, top=0.5, bottom=0.5)

    salida.seek(0)
    return salida.getvalue()


def cargar_tabla_completa_supabase(nombre_tabla):
    """
    Lee una tabla completa de Supabase usando select('*').

    De esta forma el respaldo incluye también columnas que la interfaz no
    muestra, como costos, auditoría u otros campos añadidos posteriormente.
    Esta función es únicamente de lectura: no inserta, actualiza ni elimina.
    """
    filas = []
    desde = 0
    tamano_pagina = 1000

    while True:
        respuesta = (
            obtener_supabase()
            .table(nombre_tabla)
            .select("*")
            .range(desde, desde + tamano_pagina - 1)
            .execute()
        )
        pagina = respuesta.data or []
        filas.extend(pagina)
        if len(pagina) < tamano_pagina:
            break
        desde += tamano_pagina

    return filas


def generar_backup_completo_supabase():
    """
    Genera un ZIP descargable con una copia completa y legible de Supabase.

    Incluye:
      - ventas_completo.csv
      - inventario_completo.csv
      - backup_completo.json
      - manifest.txt

    Se conservan todas las columnas devueltas por Supabase, incluidas las de
    costos. El ZIP se crea en memoria y no altera ninguna tabla remota.
    """
    fecha_backup = datetime.now(timezone.utc)
    tablas = {
        "ventas": cargar_tabla_completa_supabase("ventas"),
        "inventario": cargar_tabla_completa_supabase("inventario"),
    }

    manifiesto = {
        "fecha_backup_utc": fecha_backup.isoformat(),
        "origen": "Supabase - Notas de Venta NUEVO RUMBOS",
        "tablas": {},
    }

    salida = BytesIO()
    with zipfile.ZipFile(salida, "w", compression=zipfile.ZIP_DEFLATED) as archivo:
        for nombre_tabla, filas in tablas.items():
            dataframe = pd.DataFrame(filas)
            columnas = list(dataframe.columns)
            manifiesto["tablas"][nombre_tabla] = {
                "filas": len(filas),
                "columnas": columnas,
            }

            # UTF-8 con BOM para que Excel abra correctamente acentos y ñ.
            csv_bytes = dataframe.to_csv(index=False).encode("utf-8-sig")
            archivo.writestr(f"{nombre_tabla}_completo.csv", csv_bytes)

        archivo.writestr(
            "backup_completo.json",
            json.dumps(
                {
                    "metadata": manifiesto,
                    "datos": tablas,
                },
                ensure_ascii=False,
                indent=2,
                default=str,
            ).encode("utf-8"),
        )

        lineas_manifest = [
            "COPIA DE SEGURIDAD COMPLETA - NUEVO RUMBOS",
            f"Fecha UTC: {fecha_backup.isoformat()}",
            "",
        ]
        for nombre_tabla, datos in manifiesto["tablas"].items():
            lineas_manifest.append(
                f"{nombre_tabla}: {datos['filas']} filas; "
                f"{len(datos['columnas'])} columnas"
            )
            lineas_manifest.append(
                "Columnas: " + ", ".join(datos["columnas"])
            )
            lineas_manifest.append("")

        archivo.writestr(
            "manifest.txt",
            "\n".join(lineas_manifest).encode("utf-8"),
        )

    salida.seek(0)
    nombre_archivo = (
        "backup_supabase_nuevo_rumbos_"
        f"{fecha_backup.strftime('%Y%m%d_%H%M%S')}.zip"
    )
    return salida.getvalue(), nombre_archivo, manifiesto


def cargar_tabla(sede):
    """Carga las notas existentes sin modificar ningún dato remoto."""
    filas_remotas = []
    desde = 0
    tamano_pagina = 1000

    while True:
        respuesta = (
            obtener_supabase()
            .table("ventas")
            .select(
                "id,nro_nota,fecha,cliente,categoria,descripcion,cantidad,"
                "precio_unitario,precio_total,precio_dolar"
            )
            .eq("sede", sede)
            .order("id")
            .range(desde, desde + tamano_pagina - 1)
            .execute()
        )
        pagina = respuesta.data or []
        filas_remotas.extend(pagina)
        if len(pagina) < tamano_pagina:
            break
        desde += tamano_pagina

    datos = []
    for fila in filas_remotas:
        fecha = pd.to_datetime(fila.get("fecha"), errors="coerce")
        fecha = fecha.date() if not pd.isna(fecha) else datetime.today().date()
        categoria = str(fila.get("categoria") or "").strip()
        descripcion = str(fila.get("descripcion") or "").strip()

        datos.append(
            {
                "_id": entero_seguro(fila.get("id")),
                "Eliminar": False,
                "Nro Nota": entero_seguro(fila.get("nro_nota")),
                "Fecha": fecha,
                "Cliente": fila.get("cliente") or "",
                "Categoría": categoria,
                "Descripción": descripcion,
                "Cantidad": entero_seguro(fila.get("cantidad")),
                "Precio Unitario (Bs.)": decimal_seguro(
                    fila.get("precio_unitario")
                ),
                "Precio Total (Bs.)": decimal_seguro(fila.get("precio_total")),
                "Precio en Dólar": decimal_seguro(fila.get("precio_dolar")),
            }
        )

    return pd.DataFrame(datos, columns=COLUMNAS_NOTAS)


def crear_nota(sede):
    """Añade una fila nueva sin alterar las notas ya guardadas."""
    if not puede_editar_sede(sede):
        st.error("No tienes permiso para añadir notas en esta sede.")
        return 0

    payload = {
        "sede": sede,
        "nro_nota": 0,
        "fecha": datetime.today().date().isoformat(),
        "cliente": "",
        "categoria": "",
        "descripcion": "",
        "cantidad": 1,
        "precio_unitario": 0.0,
        "precio_dolar": 0.0,
        "actualizado_por": usuario_actual(),
        "updated_at": ahora_utc(),
    }
    obtener_supabase().table("ventas").insert(payload).execute()
    return 1


def eliminar_notas(ids, sede):
    """Elimina únicamente filas de una sede autorizada y por su ID remoto."""
    if not puede_editar_sede(sede):
        st.error("No tienes permiso para eliminar notas en esta sede.")
        return 0

    ids_validos = sorted(
        {
            entero_seguro(valor)
            for valor in ids
            if entero_seguro(valor) > 0
        }
    )
    if not ids_validos:
        return 0

    (
        obtener_supabase()
        .table("ventas")
        .delete()
        .eq("sede", str(sede).strip().upper())
        .in_("id", ids_validos)
        .execute()
    )
    return len(ids_validos)


def guardar_cambios_notas(sede, anterior, editado):
    """
    Actualiza solo las filas que cambiaron y solo las columnas de la interfaz.
    Las columnas adicionales existentes en Supabase, incluidas las de costos,
    no forman parte del payload y por tanto no se sobrescriben.
    """
    if not puede_editar_sede(sede):
        return 0

    if anterior is None or editado is None or anterior.empty or editado.empty:
        return 0

    anteriores = {
        entero_seguro(fila.get("_id")): fila
        for _, fila in anterior.iterrows()
        if entero_seguro(fila.get("_id")) > 0
    }
    cantidad_cambios = 0

    for _, fila in editado.iterrows():
        identificador = entero_seguro(fila.get("_id"))
        if identificador <= 0 or identificador not in anteriores:
            continue

        antes = payload_nota(sede, anteriores[identificador])
        despues = payload_nota(sede, fila)
        if antes == despues:
            continue

        despues.update(
            {
                "actualizado_por": usuario_actual(),
                "updated_at": ahora_utc(),
            }
        )
        (
            obtener_supabase()
            .table("ventas")
            .update(despues)
            .eq("id", identificador)
            .eq("sede", sede)
            .execute()
        )
        cantidad_cambios += 1

    return cantidad_cambios


def cargar_inventario():
    """Carga los ingresos existentes de la tabla inventario."""
    inventario = {
        sede: {categoria: 0 for categoria in CATEGORIAS_PRODUCTO}
        for sede in SEDES
    }

    respuesta = (
        obtener_supabase()
        .table("inventario")
        .select("sede,categoria,ingreso")
        .execute()
    )

    for fila in respuesta.data or []:
        sede = fila.get("sede")
        categoria = fila.get("categoria")
        if sede in inventario and categoria in inventario[sede]:
            inventario[sede][categoria] = max(
                0, entero_seguro(fila.get("ingreso"))
            )

    return inventario


def guardar_inventario_cambios(cambios):
    """
    Guarda únicamente las celdas de inventario que realmente cambiaron.

    Cada combinación (sede, categoría) se envía una sola vez. Esto evita
    sobrescribir datos no modificados y también evita errores de Supabase
    cuando una categoría pudiera aparecer repetida en la lista de productos.
    """
    filas_unicas = {}

    for cambio in cambios or []:
        sede = str(cambio.get("sede", "")).strip().upper()
        categoria = str(cambio.get("categoria", "")).strip()

        if sede not in SEDES or categoria not in CATEGORIAS_PRODUCTO:
            continue

        filas_unicas[(sede, categoria)] = {
            "sede": sede,
            "categoria": categoria,
            "ingreso": max(0, entero_seguro(cambio.get("ingreso", 0))),
            "actualizado_por": usuario_actual(),
            "updated_at": ahora_utc(),
        }

    filas = list(filas_unicas.values())
    if not filas:
        return 0

    (
        obtener_supabase()
        .table("inventario")
        .upsert(filas, on_conflict="sede,categoria")
        .execute()
    )
    return len(filas)

def version_editor(sede):
    """Devuelve la versión visual actual del editor de una sede."""
    clave = f"_version_editor_{sede}"
    return entero_seguro(st.session_state.get(clave, 0), 0)


def limpiar_estado_editor(sede=None):
    """
    Obliga a AgGrid a reconstruirse con los datos recién cargados.

    Cambiar la versión de la clave elimina la copia visual antigua que podía
    seguir mostrando una fila ya borrada hasta recargar manualmente la página.
    """
    sedes_a_limpiar = SEDES if sede is None else (sede,)

    for nombre_sede in sedes_a_limpiar:
        clave_version = f"_version_editor_{nombre_sede}"
        st.session_state[clave_version] = (
            entero_seguro(st.session_state.get(clave_version, 0), 0) + 1
        )


def recargar_sede(sede):
    st.session_state.tablas[sede] = cargar_tabla(sede)
    limpiar_estado_editor(sede)




